# Step 2: Send a task message to the agent
curl -s -X POST http://invoice-agent.nexora.local:9001/a2a \
  -H "Content-Type: application/json" \
  -d '{
    "id": "task-001",
    "message": {
      "role": "user",
      "parts": [{ "type": "text", "text": "Look up invoice INV-2026-045" }]
    }
  }'

